steps.action_code:
sleep_candidates = []
for alarm in initial_alarms:
    normalized_label = ' '.join(alarm['label'].lower().replace('-', ' ').replace('_', ' ').split())
    score = 0
    if normalized_label == 'go to sleep':
        score = 100
    elif normalized_label in ('bedtime', 'bed time', 'sleep', 'go to bed'):
        score = 90
    elif 'go to sleep' in normalized_label or 'go to bed' in normalized_label:
        score = 80
    elif 'bedtime' in normalized_label or 'bed time' in normalized_label:
        score = 70
    elif 'sleep' in normalized_label and 'wake' not in normalized_label:
        score = 60
    elif normalized_label in ('night', 'night alarm'):
        score = 50
    if score > 0:
        sleep_candidates.append((score, alarm))
if not sleep_candidates:
    raise RuntimeError('No go-to-sleep alarm candidate was found')
best_sleep_score = max(score for score, alarm in sleep_candidates)
best_sleep_matches = [alarm for score, alarm in sleep_candidates if score == best_sleep_score]
if len(best_sleep_matches) != 1:
    raise RuntimeError('The go-to-sleep alarm is ambiguous')
target_alarm = best_sleep_matches[0]
target_alarm_id = target_alarm['alarm_id']
target_original_time = target_alarm['time']
target_original_enabled = target_alarm['enabled']
time_parts = target_original_time.split(':')
target_new_minutes = (int(time_parts[0]) * 60 + int(time_parts[1]) + 20) % (24 * 60)
target_new_time = f'{target_new_minutes // 60:02d}:{target_new_minutes % 60:02d}'
print({'candidates': [{'alarm_id': alarm['alarm_id'], 'label': alarm['label'], 'time': alarm['time'], 'score': score} for score, alarm in sleep_candidates], 'selected_alarm_id': target_alarm_id, 'current_time': target_original_time, 'new_time': target_new_time})

